import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Verify {public static void main(String[] args)throws Exception{int count=0;try(ZipFile z=new ZipFile(args[0])){for(ZipEntry e:Collections.list(z.entries())){if(!e.getName().endsWith(".class"))continue;ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);for(MethodNode m:c.methods){if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))!=0)continue;new Analyzer<>(new BasicVerifier()).analyze(c.name,m);count++;}}}System.out.println("Bytecode methods analyzed: "+count);}}
